import { NextResponse } from "next/server"
import { normalizeArchiveCategory } from "@/lib/archive-categories"
import {
  ArchiveStoreVersionConflictError,
  readArchiveStore,
  writeArchiveStore,
  type ArchivePostRecord,
} from "@/lib/archive-store"
import {
  ADMIN_SESSION_COOKIE_NAME,
  readCookieValue,
  verifyAdminSessionToken,
} from "@/lib/admin-session"

interface CreateArchivePostBody {
  title?: string
  content?: string
  category?: string
  customCategory?: string
}

interface ReplaceArchiveStoreBody {
  version?: number
  posts?: ArchivePostRecord[]
  customCategories?: string[]
}

function normalizeCustomCategoryName(input?: string | null): string | undefined {
  if (typeof input !== "string") {
    return undefined
  }

  const normalized = input.replace(/\s+/g, " ").trim()
  return normalized ? normalized : undefined
}

function isWriteAuthorized(request: Request) {
  const token = readCookieValue(request.headers.get("cookie"), ADMIN_SESSION_COOKIE_NAME)
  return verifyAdminSessionToken(token)
}

export async function GET() {
  const data = await readArchiveStore()
  return NextResponse.json(data)
}

export async function POST(request: Request) {
  if (!isWriteAuthorized(request)) {
    return NextResponse.json({ message: "인증이 필요합니다." }, { status: 401 })
  }

  try {
    const body = (await request.json()) as CreateArchivePostBody
    const title = typeof body.title === "string" ? body.title.trim() : ""
    const content = typeof body.content === "string" ? body.content : ""

    if (!title || !content.trim()) {
      return NextResponse.json(
        { message: "title과 content는 필수입니다." },
        { status: 400 }
      )
    }

    const now = new Date().toISOString()
    const newPost: ArchivePostRecord = {
      id: Date.now().toString(),
      title,
      content,
      createdAt: now,
      category: normalizeArchiveCategory(body.category),
      customCategory: normalizeCustomCategoryName(body.customCategory),
    }

    const current = await readArchiveStore()
    const saved = await writeArchiveStore({
      posts: [newPost, ...current.posts],
      customCategories: current.customCategories,
    })

    return NextResponse.json({
      post: newPost,
      data: saved,
    })
  } catch {
    return NextResponse.json(
      { message: "아카이브 저장 중 오류가 발생했습니다." },
      { status: 400 }
    )
  }
}

export async function PUT(request: Request) {
  if (!isWriteAuthorized(request)) {
    return NextResponse.json({ message: "인증이 필요합니다." }, { status: 401 })
  }

  try {
    const body = (await request.json()) as ReplaceArchiveStoreBody
    const nextData = {
      posts: Array.isArray(body.posts) ? body.posts : [],
      customCategories: Array.isArray(body.customCategories) ? body.customCategories : [],
    }

    const saved = await writeArchiveStore(
      nextData,
      typeof body.version === "number" && Number.isFinite(body.version)
        ? Math.floor(body.version)
        : undefined
    )

    return NextResponse.json(saved)
  } catch (error) {
    if (error instanceof ArchiveStoreVersionConflictError) {
      return NextResponse.json(
        {
          message: "다른 변경사항이 먼저 저장되어 충돌이 발생했습니다.",
          data: error.current,
        },
        { status: 409 }
      )
    }

    return NextResponse.json(
      { message: "아카이브 동기화 중 오류가 발생했습니다." },
      { status: 400 }
    )
  }
}
