import "server-only"

import { mkdir, readFile, rename, writeFile } from "node:fs/promises"
import { dirname, join } from "node:path"
import { normalizeArchiveCategory, type ArchiveCategory } from "@/lib/archive-categories"

export interface ArchivePostRecord {
  id: string
  title: string
  content: string
  createdAt: string
  updatedAt?: string
  category: ArchiveCategory
  customCategory?: string
}

export interface ArchiveStoreData {
  version: number
  posts: ArchivePostRecord[]
  customCategories: string[]
}

export class ArchiveStoreVersionConflictError extends Error {
  current: ArchiveStoreData

  constructor(current: ArchiveStoreData) {
    super("Archive store version conflict")
    this.name = "ArchiveStoreVersionConflictError"
    this.current = current
  }
}

const ARCHIVE_STORE_FILE_PATH = join(process.cwd(), "data", "archive-store.json")
let writeQueue: Promise<void> = Promise.resolve()

function normalizeCustomCategoryName(input?: string | null): string | undefined {
  if (typeof input !== "string") {
    return undefined
  }

  const normalized = input.replace(/\s+/g, " ").trim()
  return normalized ? normalized : undefined
}

function dedupeCustomCategories(categories: readonly string[]): string[] {
  const uniqueKeys = new Set<string>()
  const result: string[] = []

  for (const category of categories) {
    const normalized = normalizeCustomCategoryName(category)
    if (!normalized) {
      continue
    }

    const key = normalized.toLowerCase()
    if (uniqueKeys.has(key)) {
      continue
    }

    uniqueKeys.add(key)
    result.push(normalized)
  }

  return result
}

function normalizeArchiveStoreData(raw: unknown): ArchiveStoreData {
  if (!raw || typeof raw !== "object") {
    return { version: 0, posts: [], customCategories: [] }
  }

  const source = raw as Record<string, unknown>
  const version =
    typeof source.version === "number" && Number.isFinite(source.version) && source.version >= 0
      ? Math.floor(source.version)
      : 0
  const rawPosts = Array.isArray(source.posts) ? source.posts : []
  const rawCustomCategories = Array.isArray(source.customCategories)
    ? source.customCategories
    : []

  const posts: ArchivePostRecord[] = rawPosts
    .map((item) => {
      if (!item || typeof item !== "object") {
        return null
      }

      const candidate = item as Record<string, unknown>
      const id = typeof candidate.id === "string" ? candidate.id.trim() : ""
      const title = typeof candidate.title === "string" ? candidate.title.trim() : ""
      const content = typeof candidate.content === "string" ? candidate.content : ""
      const createdAt =
        typeof candidate.createdAt === "string" && candidate.createdAt.trim()
          ? candidate.createdAt
          : new Date().toISOString()
      const updatedAt =
        typeof candidate.updatedAt === "string" && candidate.updatedAt.trim()
          ? candidate.updatedAt
          : undefined
      const category = normalizeArchiveCategory(candidate.category)
      const customCategory = normalizeCustomCategoryName(
        typeof candidate.customCategory === "string" ? candidate.customCategory : undefined
      )

      if (!id || !title || !content.trim()) {
        return null
      }

      return {
        id,
        title,
        content,
        createdAt,
        updatedAt,
        category,
        customCategory,
      }
    })
    .filter((item): item is ArchivePostRecord => Boolean(item))

  const categoriesFromPosts = posts
    .map((post) => normalizeCustomCategoryName(post.customCategory))
    .filter((category): category is string => Boolean(category))

  const customCategories = dedupeCustomCategories([
    ...rawCustomCategories.filter((item): item is string => typeof item === "string"),
    ...categoriesFromPosts,
  ])

  return {
    version,
    posts,
    customCategories,
  }
}

function enqueueWrite<T>(job: () => Promise<T>): Promise<T> {
  const execution = writeQueue.then(job, job)
  writeQueue = execution.then(
    () => undefined,
    () => undefined
  )

  return execution
}

async function ensureArchiveStoreFile() {
  await mkdir(dirname(ARCHIVE_STORE_FILE_PATH), { recursive: true })

  try {
    await readFile(ARCHIVE_STORE_FILE_PATH, "utf-8")
  } catch {
    await writeFile(
      ARCHIVE_STORE_FILE_PATH,
      JSON.stringify({ version: 0, posts: [], customCategories: [] }, null, 2),
      "utf-8"
    )
  }
}

export async function readArchiveStore(): Promise<ArchiveStoreData> {
  await ensureArchiveStoreFile()

  try {
    const raw = await readFile(ARCHIVE_STORE_FILE_PATH, "utf-8")
    const parsed = JSON.parse(raw)
    return normalizeArchiveStoreData(parsed)
  } catch {
    return { version: 0, posts: [], customCategories: [] }
  }
}

export async function writeArchiveStore(
  nextData: Omit<ArchiveStoreData, "version">,
  expectedVersion?: number
): Promise<ArchiveStoreData> {
  return enqueueWrite(async () => {
    await ensureArchiveStoreFile()

    const current = await readArchiveStore()
    if (
      typeof expectedVersion === "number" &&
      Number.isFinite(expectedVersion) &&
      expectedVersion !== current.version
    ) {
      throw new ArchiveStoreVersionConflictError(current)
    }

    const normalized = normalizeArchiveStoreData({
      ...nextData,
      version: current.version + 1,
    })
    const tempPath = `${ARCHIVE_STORE_FILE_PATH}.tmp`

    await writeFile(tempPath, JSON.stringify(normalized, null, 2), "utf-8")
    await rename(tempPath, ARCHIVE_STORE_FILE_PATH)

    return normalized
  })
}
